import {catalog,activityTitle,statusLabel} from './catalog.mjs';
// Describe saved choices, never infer ability or completion from a host phase.
export function describePractice(entry,s){
 let practice='Has abierto la propuesta; no se registra cuánto se practicó.',next='Puedes leer la guía y elegir por dónde empezar.';
 if(s.numberParts){const v=s.numberParts,explored=v.rounds.some(r=>r&&(r.reference||r.checked||r.counts.some(Boolean)));practice=explored?'Exploraste una distribución y puedes revisar la imagen guardada por separado.':'Abriste el taller de seis fichas; todavía no hay una forma conservada.';next=v.rounds[1]?'Puedes revisar tus formas de seis y ocho o deshacer el último cambio de cada ronda.':'Puedes empezar cuando quieras, guardar una forma o probar con ocho. No indica dominio ni asigna un nivel.';}
 else if(s.quantity){practice=s.quantity.rounds.some(r=>r?.counts.some(Boolean))?'Distribuiste fichas entre cuencos.':'Abriste el taller de reparto.';next='Puedes volver a tu reparto, comparar los cuencos o probar otra ronda. No hace falta terminarlas todas.';}
 else if(s.biologyLab){const v=s.biologyLab;practice=v.tested?'Consultaste registros ficticios de plantas para comparar condiciones.':v.page==='guide'?'Abriste la guía para comparar plantas y entorno.':'Tu comparación contiene una pregunta y dos bandejas ficticias.';next=v.reviewed?'Puedes revisar tu explicación o dibujar otra comparación en papel.':'Puedes anticipar, consultar los registros y contrastar una explicación.';}
 else if(s.chemistryLab){const v=s.chemistryLab;practice=v.cells.some(Boolean)?'Construiste un modelo con fichas de sustancias imaginarias.':'Abriste la guía de modelos de sustancias y mezclas.';next=v.reviewed?'Puedes revisar las identidades representadas o dibujar otro modelo en papel.':'Puedes anticipar la clasificación y explicar qué identidades aparecen.';}
 else if(s.balance){const v=s.balance;practice=v.last?'Probaste una configuración de la balanza idealizada.':'Abriste el taller del modelo de balanza.';next=v.comparison?'Puedes comparar las series conservadas o revisar los productos masa por distancia.':'Puedes anticipar otro resultado y explorar una distancia diferente.';}
 else if(s.contextScene){const v=s.contextScene;practice=v.objects.some(Boolean)?'Construiste una escena de objetos y etiquetas en este idioma.':'Abriste el constructor de escenas de este idioma.';next=v.original?'Puedes revisar las etiquetas y comparar con tu primera escena.':'Puedes colocar objetos, elegir etiquetas y consultar su correspondencia.';}
 else if(s.argument){const v=s.argument;practice=v.claim?'Elegiste una afirmación para relacionarla con los registros ficticios.':'Abriste el taller de argumentos.';next=v.page>0?'Puedes revisar el argumento con la nueva información y distinguir conclusión de decisión.':'Puedes vincular una tarjeta, señalar un límite y revisar la relación.';}
 else if(s.composition){const v=s.composition;practice=v.cells.some(Boolean)?'Compusiste un cartel con formas.':'Abriste el taller de carteles.';next=v.original?'Puedes comparar las versiones y explicar una decisión de diseño.':'Puedes colocar formas y preparar una versión sin color.';}
 else if(s.construction){practice=s.construction.items.length?'Construiste una secuencia de piezas o instrucciones.':'Abriste el taller de construcción.';next=entry.stage==='3y'?'Con un adulto, puedes probar la regla del patrón o llevarla a gestos.':'Con un adulto, puedes probar el recorrido y revisar una dirección.';}
 else if(s.exploration){practice=entry.stage==='2y'?'Preparaste una propuesta de historia para acompañar fuera de pantalla.':'Tu comparación usa registros ficticios de distintas condiciones.';next=entry.stage==='2y'?'Aparta la pantalla y sigue la iniciativa del pequeño; no se registra su respuesta.':'Puedes revisar qué cambia entre los registros y qué permanece igual.';}
 else if(s.language||s.context){practice='Abriste un recorrido de palabras de este idioma.';next='Puedes volver a las etiquetas, probar otra elección o seguir sin audio.';}
 else if(s.phase!=='intro'){practice=entry.type==='guide'?'Abriste una guía de acompañamiento; no se registra el juego fuera de pantalla.':'Abriste la actividad; sus elecciones conservadas están disponibles para revisar.';next=entry.type==='guide'?'Puedes consultar la guía o apartar la pantalla y acompañar.':'Puedes volver a la propuesta y revisar tus elecciones con ayuda.';}
 if(entry.id==='reflection'){practice='Abriste la historia de Dani; sus decisiones no se conservan.';next='Puedes volver a imaginar distintas posibilidades, sin una única emoción correcta.';}
 return {practice,next};
}
export function progressRows(states,currentKey){
 const rows=catalog.filter(e=>Object.hasOwn(states,e.key)).map(e=>({key:e.key,title:activityTitle(e),age:e.label,phase:statusLabel(states[e.key].phase),...describePractice(e,states[e.key])}));
 return [...rows.filter(r=>r.key===currentKey),...rows.filter(r=>r.key!==currentKey)];
}
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function progressSummaryMarkup(states,currentKey){const rows=progressRows(states,currentKey);return `<section class="practice-summary" aria-labelledby="practice-summary-title"><h3 id="practice-summary-title">Lo que puedes retomar</h3><p>Este resumen describe propuestas y elecciones visibles en esta pestaña. Cerrar una sesión no demuestra que se completara el recorrido ni mide capacidad o dominio. El estado de guardado de arriba indica si se conservan al cerrar el navegador.</p>${rows.length?`<ul>${rows.map(r=>`<li><h4>${escape(r.title)}</h4><p class="quiet">${escape(r.age)} · ${escape(r.phase)}</p><p>${escape(r.practice)}</p><p>${escape(r.next)}</p><button type="button" class="action secondary" data-progress-route="${escape(r.key)}">Abrir esta propuesta</button></li>`).join('')}</ul>`:'<p>Aún no hay propuestas abiertas en esta pestaña. Puedes empezar desde una edad o un área.</p>'}</section>`;}
